def _callable_levels(self) -> List[Any]:
    # Collect every level of the callable chain: the object itself, the
    # functions wrapped by functools.wraps (__wrapped__) and the functions
    # wrapped by functools.partial (.func), recursively. Any of them may
    # decide how the callable has to be called.
    levels: List[Any] = []
    seen: set = set()
    current = self.call
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        levels.append(current)
        if isinstance(current, partial):
            current = current.func
        else:
            current = getattr(current, "__wrapped__", None)
    return levels

